281	  /// Picks the shape (single call+cursor vs. bounded fan-out-and-merge) per
282	  /// research.md R1.
283	  Future<Either<Failure, ({List<Entry> entries, String? nextCursor})>> _resolveEntries({
284	    required String query,
285	    required DateTime? dateFrom,
286	    required DateTime? dateTo,
287	    required Set<EntrySource> types,
288	  }) async {
289	    if (types.length <= 1) {
290	      final source = types.isEmpty ? null : types.single;
291	      if (query.isNotEmpty) {
292	        final result = await _entriesRepository.search(
293	          q: query,
294	          source: source,
295	          dateFrom: dateFrom,
296	          dateTo: dateTo,
297	        );
298	        return result.map((entries) => (entries: entries, nextCursor: null));
299	      }
300	      final result = await _entriesRepository.list(
301	        source: source,
302	        dateFrom: dateFrom,
303	        dateTo: dateTo,
304	      );
305	      return result.map((page) => (entries: page.entries, nextCursor: page.nextCursor));
306	    }
307	
308	    // 2+ entry types — bounded fan-out, one call per type (research.md R1).
309	    final calls = types.map(
310	      (source) => query.isNotEmpty
311	          ? _entriesRepository.search(q: query, source: source, dateFrom: dateFrom, dateTo: dateTo)
312	          : _entriesRepository
313	                .list(source: source, dateFrom: dateFrom, dateTo: dateTo, limit: 50)
314	                .then((r) => r.map((page) => page.entries)),
315	    );
316	    final results = await Future.wait(calls);
317	    for (final r in results) {
318	      if (r.isLeft()) {
319	        return r.map((_) => (entries: <Entry>[], nextCursor: null));
320	      }
321	    }
322	    final merged = EntryMerger.mergeMany(
323	      sources: [for (final r in results) r.getOrElse((_) => [])],
324	      byRelevance: query.isNotEmpty,
325	    );
326	    return Right((entries: merged, nextCursor: null));
327	  }
328	
329	  @override
330	  Future<void> close() {
331	    _debounceTimer?.cancel();
332	    unawaited(_reauthController.close());
333	    return super.close();
334	  }
335	}
