      cursor: cursor,
      source: source,
      dateFrom: dateFrom,
      dateTo: dateTo,
      limit: limit,
    );
    return result.match(
      (failure) => failure is AuthExpiredFailure
          ? _retryAfterSilentRefresh(
              () => _remoteDataSource.list(
                cursor: cursor,
                source: source,
                dateFrom: dateFrom,
                dateTo: dateTo,
                limit: limit,
              ),
            )
          : Future.value(Left(failure)),
      (page) => Future.value(Right(page)),
    );
  }

  @override
  Future<Either<Failure, List<Entry>>> search({
    String? q,
    EntrySource? source,
    DateTime? dateFrom,
    DateTime? dateTo,
    int limit = 50,
  }) async {
    final result = await _remoteDataSource.search(
      q: q,
      source: source,
      dateFrom: dateFrom,
      dateTo: dateTo,
      limit: limit,
    );
    return result.match(
      (failure) => failure is AuthExpiredFailure
          ? _retryAfterSilentRefresh(
              () => _remoteDataSource.search(
                q: q,
                source: source,
                dateFrom: dateFrom,
                dateTo: dateTo,
                limit: limit,
              ),
            )
          : Future.value(Left(failure)),
      (entries) => Future.value(Right(entries)),
    );
  }

  @override
  Future<Either<Failure, Entry>> getById(String id) async {
    final result = await _remoteDataSource.getById(id);
    return result.match(
      (failure) => failure is AuthExpiredFailure
          ? _retryAfterSilentRefresh(() => _remoteDataSource.getById(id))
